<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class CitaRequest extends FormRequest {
 public function authorize(): bool{return true;}
 protected function prepareForValidation(): void { $optional=['Sintomas','ObservacionesMedicas','TratamientoGeneral','PresionArterial','Temperatura','Peso']; $d=[]; foreach($optional as $k) if($this->exists($k)&&$this->input($k)==='') $d[$k]=null; foreach(($this->input('detalles')??[]) as $i=>$linea) foreach(['CodigoProducto','SubtipoDetalle','Dosis','Frecuencia','Duracion','Indicaciones','Resultado','Cantidad'] as $k) if(array_key_exists($k,$linea)&&$linea[$k]==='') $d["detalles.$i.$k"]=null; if($d)$this->merge($d); }
 public function rules(): array { $partial=$this->isMethod('PATCH'); $r=[]; foreach(['CodigoPaciente','CodigoColaborador','CodigoSucursal','CodigoEspecialidad'] as $k)$r[$k]=array_merge($partial?['sometimes']:[],['required','string','regex:/^[a-fA-F0-9]{24}$/']); $r['FechaHoraCita']=array_merge($partial?['sometimes']:[],['required','date']); $r['TipoAtencion']=array_merge($partial?['sometimes']:[],['required','string','max:30']); $r['MotivoConsulta']=array_merge($partial?['sometimes']:[],['required','string','max:500']); foreach(['Sintomas'=>1000,'ObservacionesMedicas'=>1000,'TratamientoGeneral'=>1000,'PresionArterial'=>20] as $k=>$max)$r[$k]=array_merge($partial?['sometimes']:[],['nullable','string','max:'.$max]); $r['Temperatura']=array_merge($partial?['sometimes']:[],['nullable','numeric','between:0,999.99']); $r['Peso']=array_merge($partial?['sometimes']:[],['nullable','numeric','between:0,9999.99']); $r['Estado']=array_merge($partial?['sometimes']:[],['required','string','max:30']); $r['detalles']=array_merge($partial?['sometimes']:[],['required','array']); $r['detalles.*.TipoDetalle']=['required','string','max:40']; $r['detalles.*.DescripcionDetalle']=['required','string','max:1000']; foreach(['SubtipoDetalle'=>100,'Dosis'=>100,'Frecuencia'=>100,'Duracion'=>100,'Indicaciones'=>500,'Resultado'=>1000] as $k=>$max)$r['detalles.*.'.$k]=['nullable','string','max:'.$max]; $r['detalles.*.Cantidad']=['nullable','numeric','between:0,9999999999.99']; $r['detalles.*.FechaRegistro']=['sometimes','date']; $r['detalles.*.Estado']=['sometimes','string','max:20']; $r['detalles.*.CodigoProducto']=['nullable','string','regex:/^[a-fA-F0-9]{24}$/']; foreach(['id','_id','CodigoCitaConsulta','CodigoCitaConsultaDetalle'] as $k)$r[$k]=['prohibited']; foreach(['id','_id','CodigoDetalle','CodigoCitaConsulta'] as $k)$r['detalles.*.'.$k]=['prohibited']; return $r; }
}
